#btnCrouch { width: 54px; height: 54px; right: 116px; bottom: 82px; }
/* 换弹：FIRE 正上方 */
#btnReload { right: 16px; bottom: 108px; }
/* 武器切换：右缘竖排（1 上 2 下），保证任何机型都有换枪入口 */
.wpn-btn {
  width: 48px; height: 48px;
  right: 10px;
  background: rgba(255,255,255,0.12);
