  background: rgba(245,181,58,0.6);
  border-color: rgba(245,181,58,0.9);
}
.wpn-btn[data-slot="1"] { bottom: 176px; }
.wpn-btn[data-slot="2"] { bottom: 232px; }
.wpn-btn[data-slot="3"] { bottom: 288px; }

